AAA;IACA,oCAAA;IACA,mBAAA;AACA;;AAEA,8BAAA;AACA;IACA,mBAAA;AACA;;AAEA,kDAAA;AACA;IACA,wCAAA;IACA,+DAAA;IACA,+CAAA;IACA,iBAAA;IACA,gBAAA;IACA,gBAAA;AACA;AAEA;;IAEA,aAAA;AACA;AAEA;IACA,WAAA;IACA,yBAAA;IACA,gBAAA;AACA;AAEA;;IAEA,iBAAA;IACA,gBAAA;IACA,4CAAA;AACA;AAEA;IACA,gBAAA;IACA,oCAAA;IACA,sEAAA;AACA;AAEA;IACA,aAAA;IACA,QAAA;IACA,mBAAA;AACA;AAEA;IACA,qBAAA;IACA,gBAAA;IACA,mCAAA;IACA,iBAAA;AACA;AAEA;IACA,wCAAA;IACA,oCAAA;AACA;AAEA;IACA,8CAAA;IACA,mCAAA;AACA;AAEA;IACA,aAAA;IACA,gBAAA;AACA;AAEA;IACA,aAAA;IACA,mBAAA;AACA;AAEA;IACA,aAAA;IACA,QAAA;IACA,kBAAA;AACA;AAEA;IACA,aAAA;IACA,4DAAA;IACA,QAAA;IACA,iBAAA;IACA,gBAAA;IACA,YAAA;IACA,qCAAA;IACA,mCAAA;AACA;AAEA;IACA,cAAA;IACA,YAAA;IACA,yCAAA;IACA,mCAAA;AACA;AAEA;IACA,aAAA;IACA,yBAAA;IACA,QAAA;IACA,gBAAA;IACA,iBAAA;IACA,yCAAA;AACA;;AAEA,gCAAA;AACA;IACA,WAAA;IACA,eAAA;AACA;AAEA;IACA,eAAA;AACA;AAEA;IACA,yCAAA;AACA;AAEA;IACA,wCAAA;AACA;AAEA;IACA,aAAA;AACA;AAEA;IACA,oCAAA;IACA,gBAAA;AACA;AAEA;IACA,aAAA;IACA,eAAA;IACA,QAAA;AACA;AAEA;IACA,YAAA;IACA,yCAAA;IACA,mCAAA;AACA;AAEA;IACA,qBAAA;IACA,iBAAA;IACA,8CAAA;IACA,mCAAA;IACA,mBAAA;IACA,iBAAA;AACA;AAEA;IACA,WAAA;IACA,yBAAA;IACA,gBAAA;AACA;AAEA;;IAEA,gBAAA;IACA,4CAAA;IACA,gBAAA;IACA,sBAAA;AACA;AAEA;IACA,gBAAA;IACA,eAAA;IACA,oCAAA;IACA,sEAAA;AACA;AAEA;IACA,sBAAA;IACA,iBAAA;AACA;AAEA;IACA;4EACA;IACA,gBAAA;AACA;AAEA;IACA,sBAAA;IACA,YAAA;IACA,gBAAA;IACA,oBAAA;IACA,kBAAA;AACA;AAEA;IACA,2BAAA;IACA,gBAAA;AACA;AAEA;IACA,oCAAA;AACA;AAEA;IACA,yCAAA;AACA;AAEA;;IAEA,oCAAA;AACA;AAEA;IACA,aAAA;IACA,mBAAA;IACA,QAAA;IACA,mBAAA;IACA,oCAAA;AACA;AAEA;IACA;gEACA;IACA,mBAAA;AACA;AAEA;IACA,kBAAA;AACA;AAEA;IACA,eAAA;AACA;AAEA;IACA,2BAAA;AACA;AAEA;IACA,2BAAA;AACA;AAEA;IACA,2BAAA;AACA;AAEA;IACA,yBAAA;AACA;AAEA;IACA,oCAAA;AACA;AAEA;IACA,kBAAA;IACA,eAAA;IACA,gBAAA;AACA;AAEA;IACA,oCAAA;IACA,eAAA;AACA;AAEA;IACA,oCAAA;AACA;AAEA;IACA,yBAAA;IACA,eAAA;IACA,SAAA;AACA;AAEA;IACA,aAAA;IACA,aAAA;IACA,sBAAA;IACA,SAAA;AACA;AAEA;IACA,oCAAA;IACA,eAAA;IACA,SAAA;AACA;AAEA;IACA,4BAAA;AACA","sourcesContent":["<template>\n    <div class=\"settings-view\">\n        <div class=\"view-header\">\n            <h2>{{ t('worktime', 'Einstellungen') }}</h2>\n        </div>\n\n        <NcLoadingIcon v-if=\"loading\" :size=\"44\" />\n\n        <div v-else class=\"settings-layout\">\n            <nav class=\"settings-nav\" :aria-label=\"t('worktime', 'Einstellungs-Navigation')\">\n                <template v-for=\"group in navGroups\">\n                    <div v-if=\"group.items.length\" :key=\"group.label\" class=\"settings-nav-group\">\n                        {{ group.label }}\n                    </div>\n                    <button v-for=\"item in group.items\"\n                        :key=\"item.id\"\n                        class=\"settings-nav-item\"\n                        :class=\"{ active: activeSection === item.id }\"\n                        @click=\"setActiveSection(item.id)\">\n                        <component :is=\"item.icon\" :size=\"18\" />\n                        {{ item.label }}\n                    </button>\n                </template>\n            </nav>\n\n            <div class=\"settings-content\">\n\n            <NcSettingsSection v-if=\"canManageEmployees\"\n                v-show=\"activeSection === 'sec-mitarbeiter'\"\n                id=\"sec-mitarbeiter\" :name=\"t('worktime', 'Mitarbeiter')\">\n                <div class=\"section-header-actions\">\n                    <NcButton type=\"primary\" @click=\"openNewEmployeeForm\">\n                        <template #icon>\n                            <Plus :size=\"20\" />\n                        </template>\n                        {{ t('worktime', 'Neuer Mitarbeiter') }}\n                    </NcButton>\n                </div>\n\n                <EmployeeList\n                    :employees=\"employees\"\n                    @correct=\"startCorrection\"\n                    @edit=\"editEmployee\"\n                    @rest=\"handleSetResting\"\n                    @reactivate=\"handleReactivate\"\n                    @delete=\"handleDeleteEmployee\" />\n\n                <NcModal v-if=\"showEmployeeForm\"\n                    :name=\"editingEmployee ? t('worktime', 'Mitarbeiter bearbeiten') : t('worktime', 'Neuer Mitarbeiter')\"\n                    @close=\"closeEmployeeForm\">\n                    <EmployeeForm\n                        :employee=\"editingEmployee\"\n                        :default-federal-state=\"settings.default_federal_state || 'BY'\"\n                        @saved=\"onEmployeeSaved\"\n                        @cancel=\"closeEmployeeForm\" />\n                </NcModal>\n            </NcSettingsSection>\n\n            <NcSettingsSection v-if=\"canManageEmployees\"\n                v-show=\"activeSection === 'sec-abteilungen'\"\n                id=\"sec-abteilungen\" :name=\"t('worktime', 'Abteilungen')\">\n                <div class=\"section-header-actions\">\n                    <NcButton type=\"primary\" @click=\"openNewDepartmentForm\">\n                        <template #icon>\n                            <Plus :size=\"20\" />\n                        </template>\n                        {{ t('worktime', 'Neue Abteilung') }}\n                    </NcButton>\n                </div>\n\n                <DepartmentList\n                    :departments=\"allDepartments\"\n                    @edit=\"editDepartment\"\n                    @delete=\"handleDeleteDepartment\" />\n\n                <NcModal v-if=\"showDepartmentForm\"\n                    :name=\"editingDepartment ? t('worktime', 'Abteilung bearbeiten') : t('worktime', 'Neue Abteilung')\"\n                    @close=\"closeDepartmentForm\">\n                    <DepartmentForm\n                        :department=\"editingDepartment\"\n                        @saved=\"onDepartmentSaved\"\n                        @cancel=\"closeDepartmentForm\" />\n                </NcModal>\n            </NcSettingsSection>\n\n            <NcSettingsSection v-if=\"canManageProjects\"\n                v-show=\"activeSection === 'sec-projekte'\"\n                id=\"sec-projekte\" :name=\"t('worktime', 'Projekte')\">\n                <div class=\"section-header-actions\">\n                    <NcButton type=\"primary\" @click=\"openNewProjectForm\">\n                        <template #icon>\n                            <Plus :size=\"20\" />\n                        </template>\n                        {{ t('worktime', 'Neues Projekt') }}\n                    </NcButton>\n                </div>\n\n                <ProjectList\n                    :projects=\"allProjects\"\n                    @edit=\"editProject\"\n                    @delete=\"handleDeleteProject\" />\n\n                <NcModal v-if=\"showProjectForm\"\n                    :name=\"editingProject ? t('worktime', 'Projekt bearbeiten') : t('worktime', 'Neues Projekt')\"\n                    @close=\"closeProjectForm\">\n                    <ProjectForm\n                        :project=\"editingProject\"\n                        @saved=\"onProjectSaved\"\n                        @cancel=\"closeProjectForm\" />\n                </NcModal>\n            </NcSettingsSection>\n\n            <NcSettingsSection v-if=\"canManageSettings\"\n                v-show=\"activeSection === 'sec-berechtigungen'\"\n                id=\"sec-berechtigungen\" :name=\"t('worktime', 'Berechtigungen')\">\n                <div class=\"form-group\">\n                    <label>{{ t('worktime', 'HR-Manager') }} <InfoIcon>{{ t('worktime', 'Admin: Volle Rechte (automatisch). HR-Manager: Mitarbeiter verwalten und Anträge genehmigen (manuell zuweisen). Vorgesetzter: Genehmigt Zeiten seines Teams (automatisch). Mitarbeiter: Eigene Zeiten erfassen (automatisch).') }}</InfoIcon></label>\n                    <NcSelect\n                        v-model=\"selectedHrManagers\"\n                        :options=\"principalOptions\"\n                        :multiple=\"true\"\n                        :close-on-select=\"false\"\n                        :placeholder=\"t('worktime', 'Benutzer oder Gruppen auswählen')\"\n                        label=\"label\"\n                        @input=\"saveHrManagers\">\n                        <template #option=\"{ label, sublabel, type }\">\n                            <div class=\"principal-option\">\n                                <AccountGroup v-if=\"type === 'group'\" :size=\"20\" />\n                                <Account v-else :size=\"20\" />\n                                <span class=\"principal-label\">{{ label }}</span>\n                                <span class=\"principal-sublabel\">{{ sublabel }}</span>\n                            </div>\n                        </template>\n                    </NcSelect>\n                </div>\n            </NcSettingsSection>\n\n            <NcSettingsSection v-if=\"canManageSettings\"\n                v-show=\"activeSection === 'sec-firmendaten'\"\n                id=\"sec-firmendaten\" :name=\"t('worktime', 'Firmendaten')\"\n                :description=\"t('worktime', 'Stammdaten und Standardwerte, die für neue Mitarbeiter vorausgewählt werden.')\">\n                <div class=\"form-group\">\n                    <label for=\"companyName\">{{ t('worktime', 'Firmenname') }}</label>\n                    <input id=\"companyName\"\n                        v-model=\"settings.company_name\"\n                        type=\"text\"\n                        class=\"input-field\"\n                        @change=\"saveSetting('company_name')\">\n                </div>\n                <div class=\"form-group\">\n                    <label for=\"defaultState\">{{ t('worktime', 'Standard-Bundesland') }} <InfoIcon>{{ t('worktime', 'Neue Mitarbeiter bekommen dieses Bundesland automatisch zugewiesen. Jeder Mitarbeiter kann ein eigenes Bundesland haben — das bestimmt, welche Feiertage für ihn gelten.') }}</InfoIcon></label>\n                    <NcSelect id=\"defaultState\"\n                        v-model=\"selectedFederalState\"\n                        :options=\"federalStateOptions\"\n                        @input=\"saveSetting('default_federal_state')\" />\n                </div>\n                <div class=\"form-group\">\n                    <label for=\"timezone\">{{ t('worktime', 'Zeitzone') }} <InfoIcon>{{ t('worktime', 'Gilt für alle, deren Zeitzone Nextcloud nicht kennt, etwa nach Anmeldung per SSO oder nur über die App. Sie bestimmt die Uhrzeit der Stempeluhr und welcher Tag „heute“ ist. Die Zeitzone aus den persönlichen Nextcloud-Einstellungen hat immer Vorrang.') }}</InfoIcon></label>\n                    <NcSelect id=\"timezone\"\n                        v-model=\"selectedTimezone\"\n                        :options=\"timezoneOptions\"\n                        :clearable=\"false\"\n                        @input=\"saveSetting('timezone')\" />\n                </div>\n                <div class=\"form-row\">\n                    <div class=\"form-group\">\n                        <label for=\"weeklyHours\">{{ t('worktime', 'Standard-Wochenstunden') }} <InfoIcon>{{ t('worktime', 'Neue Mitarbeiter bekommen diese Wochenstunden voreingestellt. Sie können im Mitarbeiterprofil individuell angepasst werden.') }}</InfoIcon></label>\n                        <input id=\"weeklyHours\"\n                            v-model.number=\"settings.default_weekly_hours\"\n                            type=\"number\"\n                            min=\"0\"\n                            max=\"60\"\n                            class=\"input-field input-small\"\n                            @change=\"saveSetting('default_weekly_hours')\">\n                    </div>\n                    <div class=\"form-group\">\n                        <label for=\"vacationDays\">{{ t('worktime', 'Standard-Urlaubstage') }} <InfoIcon>{{ t('worktime', 'Neue Mitarbeiter bekommen diesen Urlaubsanspruch voreingestellt. Der tatsächliche Anspruch wird im Mitarbeiterprofil festgelegt.') }}</InfoIcon></label>\n                        <input id=\"vacationDays\"\n                            v-model.number=\"settings.default_vacation_days\"\n                            type=\"number\"\n                            min=\"0\"\n                            max=\"60\"\n                            class=\"input-field input-small\"\n                            @change=\"saveSetting('default_vacation_days')\">\n                    </div>\n                </div>\n            </NcSettingsSection>\n\n            <NcSettingsSection v-if=\"canManageSettings\"\n                v-show=\"activeSection === 'sec-arbeitszeit'\"\n                id=\"sec-arbeitszeit\" :name=\"t('worktime', 'Arbeitszeit-Regeln')\">\n                <div class=\"form-group\">\n                    <label for=\"maxDailyHours\">{{ t('worktime', 'Maximale tägliche Arbeitszeit (Stunden)') }} <InfoIcon>{{ t('worktime', 'Wenn ein Zeiteintrag diesen Wert überschreitet, wird eine Warnung angezeigt. Nach §3 ArbZG sind maximal 10 Stunden erlaubt.') }}</InfoIcon></label>\n                    <input id=\"maxDailyHours\"\n                        v-model.number=\"settings.max_daily_hours\"\n                        type=\"number\"\n                        min=\"1\"\n                        max=\"24\"\n                        step=\"0.5\"\n                        class=\"input-field input-small\"\n                        @change=\"saveSetting('max_daily_hours')\">\n                    <p class=\"help-text\">\n                        {{ t('worktime', 'Nach §3 ArbZG sind maximal 10 Stunden erlaubt (Ausnahmen möglich).') }}\n                    </p>\n                </div>\n                <div class=\"form-group\">\n                    <NcCheckboxRadioSwitch :checked.sync=\"settings.require_project\"\n                        @update:checked=\"saveSettingBool('require_project')\">\n                        {{ t('worktime', 'Projekt erforderlich') }} <InfoIcon>{{ t('worktime', 'Wenn aktiv, muss bei jedem Zeiteintrag ein Projekt ausgewählt werden — sonst lässt sich der Eintrag nicht speichern.') }}</InfoIcon>\n                    </NcCheckboxRadioSwitch>\n                </div>\n                <div class=\"form-group\">\n                    <NcCheckboxRadioSwitch :checked.sync=\"settings.require_description\"\n                        @update:checked=\"saveSettingBool('require_description')\">\n                        {{ t('worktime', 'Beschreibung erforderlich') }} <InfoIcon>{{ t('worktime', 'Wenn aktiv, muss bei jedem Zeiteintrag eine Beschreibung eingetragen werden — sonst lässt sich der Eintrag nicht speichern.') }}</InfoIcon>\n                    </NcCheckboxRadioSwitch>\n                </div>\n                <div class=\"form-group\">\n                    <NcCheckboxRadioSwitch :checked.sync=\"settings.allow_future_entries\"\n                        @update:checked=\"saveSettingBool('allow_future_entries')\">\n                        {{ t('worktime', 'Zukünftige Einträge erlauben') }} <InfoIcon>{{ t('worktime', 'Wenn deaktiviert, können Mitarbeiter nur für heute oder vergangene Tage Zeiten eintragen — nicht im Voraus.') }}</InfoIcon>\n                    </NcCheckboxRadioSwitch>\n                </div>\n            </NcSettingsSection>\n\n            <NcSettingsSection v-if=\"canManageSettings\"\n                v-show=\"activeSection === 'sec-genehmigung'\"\n                id=\"sec-genehmigung\" :name=\"t('worktime', 'Genehmigung')\"\n                :description=\"t('worktime', 'Steuert firmenweit, ob erfasste Zeiten durch Vorgesetzte freigegeben werden müssen. Diese Einstellung betrifft alle Mitarbeitenden.')\">\n                <div class=\"form-group\">\n                    <NcCheckboxRadioSwitch :checked.sync=\"settings.approval_required\"\n                        @update:checked=\"confirmApprovalToggle\">\n                        {{ t('worktime', 'Genehmigung erforderlich') }} <InfoIcon>{{ t('worktime', 'Wenn aktiv, durchlaufen Zeiteinträge einen Freigabe-Workflow: Mitarbeitende reichen den Monat ein, Vorgesetzte genehmigen ihn. Ist die Option deaktiviert, entfällt dieser Schritt und die erfassten Zeiten gelten direkt. Die Stundenberechnung ist in beiden Fällen gleich.') }}</InfoIcon>\n                    </NcCheckboxRadioSwitch>\n                </div>\n            </NcSettingsSection>\n\n            <NcSettingsSection v-if=\"canManageSettings\"\n                v-show=\"activeSection === 'sec-absenzen'\"\n                id=\"sec-absenzen\" :name=\"t('worktime', 'Teiltages-Absenzen')\"\n                :description=\"t('worktime', 'Steuert firmenweit stundenweise Krankmeldungen und Notarbeit an genehmigten Urlaubstagen. Standardmäßig deaktiviert.')\">\n                <div class=\"form-group\">\n                    <NcCheckboxRadioSwitch :checked.sync=\"settings.hourly_sick_enabled\"\n                        @update:checked=\"saveSettingBool('hourly_sick_enabled')\">\n                        {{ t('worktime', 'Stundenweise Krankmeldung erlauben') }} <InfoIcon>{{ t('worktime', 'Wenn aktiv, können Mitarbeitende an einem Einzeltag stundenweise krank sein und die restliche Zeit arbeiten. Die Krank-Stunden füllen bis zum Tagessoll, ohne künstliche Überstunden.') }}</InfoIcon>\n                    </NcCheckboxRadioSwitch>\n                </div>\n                <div class=\"form-group\">\n                    <NcCheckboxRadioSwitch :checked.sync=\"settings.emergency_work_enabled\"\n                        @update:checked=\"saveSettingBool('emergency_work_enabled')\">\n                        {{ t('worktime', 'Notarbeit im Urlaub erlauben') }} <InfoIcon>{{ t('worktime', 'Wenn aktiv, können Mitarbeitende an einem genehmigten vollen Urlaubstag Notarbeit erfassen. Der Urlaub bleibt bestehen, die Arbeit zählt als Überstunden. Eine Begründung ist Pflicht, der/die Vorgesetzte wird informiert.') }}</InfoIcon>\n                    </NcCheckboxRadioSwitch>\n                </div>\n                <div class=\"form-group\">\n                    <NcCheckboxRadioSwitch :checked.sync=\"settings.emergency_work_requires_approval\"\n                        :disabled=\"settings.emergency_work_enabled !== true\"\n                        @update:checked=\"saveSettingBool('emergency_work_requires_approval')\">\n                        {{ t('worktime', 'Notarbeit muss freigegeben werden') }} <InfoIcon>{{ t('worktime', 'Wenn aktiv, zählt eine erfasste Notarbeit erst nach Freigabe durch den/die Vorgesetzte(n) in die Überstunden. Nur relevant, wenn Notarbeit im Urlaub erlaubt ist.') }}</InfoIcon>\n                    </NcCheckboxRadioSwitch>\n                </div>\n            </NcSettingsSection>\n\n            <NcSettingsSection v-if=\"canManageSettings\"\n                v-show=\"activeSection === 'sec-pausen'\"\n                id=\"sec-pausen\" :name=\"t('worktime', 'Pausenregelung (§4 ArbZG)')\"\n                :description=\"t('worktime', 'Mindestpause gemäß deutschem Arbeitszeitgesetz')\">\n                <div class=\"form-row\">\n                    <div class=\"form-group\">\n                        <label for=\"break6h\">{{ t('worktime', 'Bei >6h Arbeitszeit (min)') }} <InfoIcon>{{ t('worktime', 'Gesetzliche Mindestpause bei mehr als 6 Stunden Arbeitszeit. Wird beim Anlegen eines Zeiteintrags automatisch als Vorschlag eingetragen.') }}</InfoIcon></label>\n                        <input id=\"break6h\"\n                            v-model.number=\"settings.min_break_minutes_6h\"\n                            type=\"number\"\n                            min=\"0\"\n                            max=\"120\"\n                            class=\"input-field input-small\"\n                            @change=\"saveSetting('min_break_minutes_6h')\">\n                    </div>\n                    <div class=\"form-group\">\n                        <label for=\"break9h\">{{ t('worktime', 'Bei >9h Arbeitszeit (min)') }} <InfoIcon>{{ t('worktime', 'Gesetzliche Mindestpause bei mehr als 9 Stunden Arbeitszeit. Wird beim Anlegen eines Zeiteintrags automatisch als Vorschlag eingetragen.') }}</InfoIcon></label>\n                        <input id=\"break9h\"\n                            v-model.number=\"settings.min_break_minutes_9h\"\n                            type=\"number\"\n                            min=\"0\"\n                            max=\"120\"\n                            class=\"input-field input-small\"\n                            @change=\"saveSetting('min_break_minutes_9h')\">\n                    </div>\n                    <div class=\"form-group\">\n                        <label for=\"maxPause\">{{ t('worktime', 'Max. Pausendauer (min)') }} <InfoIcon>{{ t('worktime', 'Läuft eine laufende Pause (Stempeluhr) länger als dieser Wert, erhält der Mitarbeiter eine Erinnerung („Bist du noch in der Pause?“).') }}</InfoIcon></label>\n                        <input id=\"maxPause\"\n                            v-model.number=\"settings.max_pause_minutes\"\n                            type=\"number\"\n                            min=\"0\"\n                            max=\"480\"\n                            class=\"input-field input-small\"\n                            @change=\"saveSetting('max_pause_minutes')\">\n                    </div>\n                </div>\n            </NcSettingsSection>\n\n            <NcSettingsSection v-if=\"canManageSettings\"\n                v-show=\"activeSection === 'sec-pdf'\"\n                id=\"sec-pdf\" :name=\"t('worktime', 'PDF-Archiv')\"\n                :description=\"t('worktime', 'Genehmigte Monatsberichte werden automatisch als PDF archiviert.')\">\n                <div class=\"form-group\">\n                    <label>{{ t('worktime', 'Archiv-Ordner') }} <InfoIcon>{{ t('worktime', 'Wenn ein Monat genehmigt wird, speichert WorkTime automatisch einen PDF-Bericht in diesem Ordner. Der Ordner liegt in deinem persönlichen Speicher — nur du als Admin hast Zugriff. Die automatische Archivierung greift nur bei aktivierter Genehmigung; ist sie deaktiviert, nutze den PDF-Export in der Monatsübersicht.') }}</InfoIcon></label>\n                    <div class=\"folder-picker\">\n                        <NcButton type=\"secondary\" @click=\"openFolderPicker\">\n                            <template #icon>\n                                <Folder :size=\"20\" />\n                            </template>\n                            {{ t('worktime', 'Ordner auswählen') }}\n                        </NcButton>\n                        <span class=\"selected-path\">\n                            {{ settings.pdf_archive_path || t('worktime', 'Nicht konfiguriert') }}\n                        </span>\n                    </div>\n                    <p class=\"help-text\">\n                        {{ t('worktime', 'PDFs werden in deinem persönlichen Ordner gespeichert. Nur du hast Zugriff.') }}\n                    </p>\n                    <p class=\"help-text\">\n                        {{ t('worktime', 'Struktur: {path}/{Jahr}/{Nachname_Vorname}/Arbeitszeitnachweis_YYYY-MM.pdf', { path: settings.pdf_archive_path || '...' }) }}\n                    </p>\n                </div>\n\n                <div v-if=\"settings.pdf_archive_path\" class=\"form-group archive-status\">\n                    <label>{{ t('worktime', 'Archivierungs-Status') }} <InfoIcon>{{ t('worktime', 'Die PDF-Archivierung läuft über einen Hintergrund-Job (ca. alle 5 Minuten). Hier siehst du ausstehende und fehlgeschlagene Archivierungen.') }}</InfoIcon></label>\n                    <NcLoadingIcon v-if=\"archiveLoading\" :size=\"20\" />\n                    <template v-else>\n                        <p class=\"help-text\">\n                            {{ t('worktime', '{pending} ausstehend · {failed} fehlgeschlagen', { pending: archiveStatus.pending, failed: archiveStatus.failed }) }}\n                        </p>\n                        <div v-if=\"archiveFailedJobs.length\" class=\"archive-failed-list\">\n                            <div v-for=\"job in archiveFail