Icon />\n            </template>\n            <template #description>\n                {{ t('worktime', 'Aktuell sind keine Team-Abwesenheiten sichtbar.') }}\n            </template>\n        </NcEmptyContent>\n    </div>\n</template>\n\n<script>\nimport NcLoadingIcon from '@nextcloud/vue/dist/Components/NcLoadingIcon.js'\nimport NcEmptyContent from '@nextcloud/vue/dist/Components/NcEmptyContent.js'\nimport AccountGroupIcon from 'vue-material-design-icons/AccountGroup.vue'\nimport FlagOutline from 'vue-material-design-icons/FlagOutline.vue'\nimport TagOutline from 'vue-material-design-icons/TagOutline.vue'\nimport { mapGetters } from 'vuex'\nimport MonthPicker from '../components/MonthPicker.vue'\nimport AbsenceTimeline from '../components/AbsenceTimeline.vue'\nimport AbsenceService from '../services/AbsenceService.js'\nimport HolidayService from '../services/HolidayService.js'\nimport { getCurrentYear, getCurrentMonth } from '../utils/dateUtils.js'\n\nexport default {\n    name: 'TeamView',\n    components: {\n        NcLoadingIcon,\n        NcEmptyContent,\n        AccountGroupIcon,\n        FlagOutline,\n        TagOutline,\n        MonthPicker,\n        AbsenceTimeline,\n    },\n    data() {\n        return {\n            month: { year: getCurrentYear(), month: getCurrentMonth() },\n            overview: [],\n            holidays: [],\n            // Standard: nach Abwesenheits-Art einfärben (Status ist über den\n            // Umschalter erreichbar).\n            colorBy: 'type',\n            loading: false,\n        }\n    },\n    computed: {\n        ...mapGetters('permissions', ['isAdmin', 'isHrManager', 'canApprove']),\n        isPrivileged() {\n            return this.isAdmin || this.isHrManager || this.canApprove\n        },\n    },\n    created() {\n        this.load()\n    },\n    methods: {\n        onMonthChange({ year, month }) {\n            this.month = { year, month }\n            this.load()\n        },\n        async load() {\n            this.loading = true\n            try {\n                const [overviewRes, holidaysRes] = await Promise.all([\n                    AbsenceService.getOverview(this.month.year, this.month.month),\n                    HolidayService.getByYear(this.month.year),\n                ])\n                this.overview = Array.isArray(overviewRes) ? overviewRes : (overviewRes?.data || [])\n                const holidayData = Array.isArray(holidaysRes) ? holidaysRes : (holidaysRes?.data || [])\n                this.holidays = holidayData.map(h => ({ date: h.date, name: h.name }))\n            } catch (error) {\n                console.error('Failed to load team overview:', error)\n                this.overview = []\n            } finally {\n                this.loading = false\n            }\n        },\n    },\n}\n</script>\n\n<style scoped>\n.team-view {\n    padding: 20px;\n    padding-left: 50px;\n    max-width: 1600px;\n}\n\n.view-header {\n    display: flex;\n    align-items: center;\n    margin-bottom: 12px;\n}\n\n.view-header h2 {\n    margin: 0;\n}\n\n.view-toolbar {\n    display: flex;\n    align-items: center;\n    flex-wrap: wrap;\n    gap: 16px;\n    margin-bottom: 20px;\n}\n\n.view-header__nav {\n    margin-left: auto;\n    display: flex;\n    align-items: center;\n}\n\n.seg {\n    display: flex;\n    background: var(--color-background-dark);\n    border-radius: var(--border-radius-element, 8px);\n    padding: 3px;\n}\n\n.seg-btn {\n    display: inline-flex;\n    align-items: center;\n    gap: 6px;\n    font-size: 13px;\n    font-weight: 600;\n    color: var(--color-text-maxcontrast);\n    background: none;\n    border: none;\n    padding: 6px 14px;\n    border-radius: var(--border-radius-element, 8px);\n    cursor: pointer;\n}\n\n.seg-btn.active {\n    background: var(--color-main-background);\n    color: var(--color-primary-element);\n    box-shadow: 0 1px 2px rgba(0, 0, 0, 0.12);\n}\n</style>\n"],"sourceRoot":""}]);
