<template>
    <div class="work-schedule-editor">
        <h4>{{ t('worktime', 'Arbeitszeitprofile') }}</h4>

        <NcLoadingIcon v-if="loading" :size="28" />

        <div v-else>
            <table v-if="schedules.length > 0" class="schedules-table">
                <thead>
                    <tr>
                        <th>{{ t('worktime', 'Gültig ab') }}</th>
                        <th class="text-right">{{ t('worktime', 'Mo') }}</th>
                        <th class="text-right">{{ t('worktime', 'Di') }}</th>
                        <th class="text-right">{{ t('worktime', 'Mi') }}</th>
                        <th class="text-right">{{ t('worktime', 'Do') }}</th>
                        <th class="text-right">{{ t('worktime', 'Fr') }}</th>
                        <th class="text-right">{{ t('worktime', 'Sa') }}</th>
                        <th class="text-right">{{ t('worktime', 'So') }}</th>
                        <th class="text-right">{{ t('worktime', 'Woche') }}</th>
                        <th class="text-right">{{ t('worktime', 'Urlaub') }}</th>
                        <th class="actions-col">{{ t('worktime', 'Aktionen') }}</th>
                    </tr>
                </thead>
                <tbody>
                    <tr v-for="schedule in schedules" :key="schedule.id">
                        <td>{{ formatDate(schedule.validFrom) }}</td>
                        <td class="text-right">{{ schedule.monHours }}</td>
                        <td class="text-right">{{ schedule.tueHours }}</td>
                        <td class="text-right">{{ schedule.wedHours }}</td>
                        <td class="text-right">{{ schedule.thuHours }}</td>
                        <td class="text-right">{{ schedule.friHours }}</td>
                        <td class="text-right">{{ schedule.satHours }}</td>
                        <td class="text-right">{{ schedule.sunHours }}</td>
                        <td class="text-right"><strong>{{ schedule.weeklyHours }}</strong></td>
                        <td class="text-right">{{ schedule.vacationDays }}</td>
                        <td class="actions-col">
                            <NcButton type="tertiary"
                                :aria-label="t('worktime', 'Bearbeiten')"
                                @click="startEdit(schedule)">
                                <template #icon>
                                    <Pencil :size="20" />
                                </template>
                            </NcButton>
                            <NcButton v-if="schedules.length > 1"
                                type="tertiary"
                                :aria-label="t('worktime', 'Löschen')"
                                @click="confirmDelete(schedule)">
                                <template #icon>
                                    <Close :size="20" />
                                </template>
                            </NcButton>
                        </td>
                    </tr>
                </tbody>
            </table>

            <div v-if="!showForm" class="add-button">
                <NcButton type="secondary" @click="startCreate">
                    <template #icon>
                        <Plus :size="20" />
                    </template>
                    {{ t('worktime', 'Neues Profil') }}
                </NcButton>
            </div>

            <div v-if="showForm" class="schedule-form">
                <h5>{{ editingSchedule ? t('worktime', 'Profil bearbeiten') : t('worktime', 'Neues Profil anlegen') }}</h5>

                <div v-if="!editingSchedule" class="form-group">
                    <label>{{ t('worktime', 'Gültig ab') }} *</label>
                    <NcDateTimePicker v-model="form.validFrom"
                        type="date"
                        :format="'DD.MM.YYYY'"
                        :disabled-date="disablePastDates" />
                </div>

                <DayHoursInput v-model="form.dayHours" :max-daily-hours="maxDailyHours" />

                <div class="form-row">
                    <div class="form-group">
                        <label>{{ t('worktime', 'Urlaubstage') }} <InfoIcon>{{ t('worktime', 'Voller Jahresanspruch bei diesem Arbeitsmuster. Bei unterjährigem Wechsel wird der tatsächliche Jahresanspruch zeitanteilig aus allen Profilen des Jahres berechnet.') }}</InfoIcon> *</label>
                        <input v-model.number="form.vacationDays"
                            type="number"
                            min="0"
                            max="60"
                            class="input-field input-small"
                            @input="vacationTouched = true">
                        <p v-if="!editingSchedule && !vacationTouched" class="hint">
                            {{ t('worktime', 'Vorschlag {days} bei {count} Arbeitstagen (30 × Tage ÷ 5) — anpassbar', { days: suggestedVacationDays, count: workingDaysInForm }) }}
                        </p>
                    </div>
                </div>

                <div class="form-actions">
                    <NcButton type="tertiary" @click="cancelForm">
                        {{ t('worktime', 'Abbrechen') }}
                    </NcButton>
                    <NcButton type="primary" :disabled="!isFormValid" @click="saveForm">
                        {{ t('worktime', 'Speichern') }}
                    </NcButton>
                </div>
            </div>
        </div>

        <NcDialog v-if="showDeleteDialog"
            :name="t('worktime', 'Profil löschen?')"
            @close="showDeleteDialog = false">
            <p>{{ t('worktime', 'Möchtest du dieses Arbeitszeitprofil wirklich löschen?') }}</p>
            <template #actions>
                <NcButton type="tertiary" @click="showDeleteDialog = false">
                    {{ t('worktime', 'Abbrechen') }}
                </NcButton>
                <NcButton type="error" @click="deleteConfirmed">
                    {{ t('worktime', 'Löschen') }}
                </NcButton>
            </template>
        </NcDialog>
    </div>
</template>

<script>
import NcButton from '@nextcloud/vue/dist/Components/NcButton.js'
import NcDateTimePicker from '@nextcloud/vue/dist/Components/NcDateTimePicker.js'
import NcDialog from '@nextcloud/vue/dist/Components/NcDialog.js'
import NcLoadingIcon from '@nextcloud/vue/dist/Components/NcLoadingIcon.js'
import Pencil from 'vue-material-design-icons/Pencil.vue'
import Close from 'vue-material-design-icons/Close.vue'
import Plus from 'vue-material-design-icons/Plus.vue'
import InfoIcon from './InfoIcon.vue'
import DayHoursInput from './DayHoursInput.vue'
import { mapGetters, mapActions } from 'vuex'
import { showError, showWarning } from '@nextcloud/dialogs'
import { formatDateISO, getLocale } from '../utils/dateUtils.js'
import { countWorkingDays, sum } from '../utils/dayHours.js'
import SettingsService from '../services/SettingsService.js'

export default {
    name: 'WorkScheduleEditor',
    components: {
        NcButton,
        NcDateTimePicker,
        NcDialog,
        NcLoadingIcon,
        Pencil,
        Close,
        Plus,
        InfoIcon,
        DayHoursInput,
    },
    props: {
        employeeId: {
            type: Number,
            required: true,
        },
        // #453: earliest selectable valid-from date (employee entry date, ISO
        // 'YYYY-MM-DD'). Null means no lower bound in the picker; the backend
        // still rejects dates inside an already-approved period.
        entryDate: {
            type: String,
            default: null,
        },
    },
    data() {
        return {
            showForm: false,
            editingSchedule: null,
            showDeleteDialog: false,
            scheduleToDelete: null,
            maxDailyHours: 10,
            // #571 (D5): once the user edits the vacation field, stop auto-
            // suggesting from the day pattern. Only ever suggests on a new profile.
            vacationTouched: false,
            form: this.getEmptyForm(),
        }
    },
    computed: {
        ...mapGetters('workSchedules', ['schedules', 'loading']),
        // #571 (D5): number of days with >0 hours in the current form.
        workingDaysInForm() {
            return countWorkingDays(this.form.dayHours)
        },
        // #571 (D5): pro-rated full-year entitlement suggestion for this pattern,
        // relative to a 5-day full-time base of 30 days (§ 5-style rounding).
        suggestedVacationDays() {
            return Math.round(30 * this.workingDaysInForm / 5)
        },
        minValidFrom() {
            // #453: allow back-dating down to the employee's entry date. Without
            // an entry date there is no lower bound in the picker.
            if (!this.entryDate) return null
            const d = new Date(this.entryDate + 'T00:00:00')
            d.setHours(0, 0, 0, 0)
            return d
        },
        isFormValid() {
            const h = this.form.dayHours
            const allWithinLimit = Object.values(h).every(v => v >= 0 && v <= this.maxDailyHours)
            return sum(h) >= 0
                && allWithinLimit
                && this.form.vacationDays >= 0
                && (this.editingSchedule || this.form.validFrom)
        },
    },
    watch: {
        employeeId: {
            immediate: true,
            async handler(id) {
                if (id) {
                    this.fetchSchedules(id)
                    try {
                        const val = await SettingsService.get('max_daily_hours')
                        if (val) {
                            this.maxDailyHours = parseFloat(val)
                        }
                    } catch (e) {
                        // Fallback bleibt bei 10
                    }
                }
            },
        },
        // #571 (D5): on a NEW profile, keep the vacation value in step with the
        // day pattern until the user overrides it. Never touches an existing
        // profile's value, never overrides a manual entry.
        'form.dayHours': {
            deep: true,
            handler() {
                if (!this.editingSchedule && !this.vacationTouched) {
                    this.form.vacationDays = this.suggestedVacationDays
                }
            },
        },
    },
    methods: {
        ...mapActions('workSchedules', ['fetchSchedules', 'createSchedule', 'updateSchedule', 'deleteSchedule']),
        getEmptyForm() {
            return {
                validFrom: new Date(),
                dayHours: { mon: 8, tue: 8, wed: 8, thu: 8, fri: 8, sat: 0, sun: 0 },
                vacationDays: 30,
            }
        },
        disablePastDates(date) {
            if (!this.minValidFrom) return false
            return date < this.minValidFrom
        },
        formatDate(dateStr) {
            if (!dateStr) return '-'
            const d = new Date(dateStr + 'T00:00:00')
            return d.toLocaleDateString(getLocale())
        },
        startCreate() {
            this.editingSchedule = null
            this.vacationTouched = false
            this.form = this.getEmptyForm()
            this.showForm = true
        },
        startEdit(schedule) {
            this.editingSchedule = schedule
            this.vacationTouched = true // never auto-change an existing profile (#571 D5)
            this.form = {
                validFrom: null,
                dayHours: {
                    mon: schedule.monHours,
                    tue: schedule.tueHours,
                    wed: schedule.wedHours,
                    thu: schedule.thuHours,
                    fri: schedule.friHours,
                    sat: schedule.satHours || 0,
                    sun: schedule.sunHours || 0,
                },
                vacationDays: schedule.vacationDays,
            }
            this.showForm = true
        },
        cancelForm() {
            this.showForm = false
            this.editingSchedule = null
        },
        async saveForm() {
            try {
                const data = {
                    dayHours: this.form.dayHours,
                    vacationDays: this.form.vacationDays,
                }

                let result
                if (this.editingSchedule) {
                    result = await this.updateSchedule({
                        employeeId: this.employeeId,
                        id: this.editingSchedule.id,
                        data,
                    })
                } else {
                    data.validFrom = this.form.validFrom
                        ? formatDateISO(this.form.validFrom)
                        : formatDateISO(new Date())
                    result = await this.createSchedule({
                        employeeId: this.employeeId,
                        data,
                    })
                }

                this.showForm = false
                this.editingSchedule = null
                this.$emit('updated')
                this.warnOnQuotaOverage(result?.quotaWarnings)
            } catch (error) {
                console.error('Failed to save schedule:', error)
                // handleApiError() puts the server text into error.message; raw axios errors have none worth showing.
                const fromServer = error && !error.isAxiosError && error.message
                showError(fromServer || t('worktime', 'Fehler beim Speichern des Profils'))
            }
        },
        confirmDelete(schedule) {
            this.scheduleToDelete = schedule
            this.showDeleteDialog = true
        },
        async deleteConfirmed() {
            try {
                const result = await this.deleteSchedule({
                    employeeId: this.employeeId,
                    id: this.scheduleToDelete.id,
                })
                this.$emit('updated')
                this.warnOnQuotaOverage(result?.quotaWarnings)
            } catch (error) {
                console.error('Failed to delete schedule:', error)
                showError(t('worktime', 'Fehler beim Löschen des Profils'))
            } finally {
                this.showDeleteDialog = false
                this.scheduleToDelete = null
            }
        },
        // #724: a profile change can raise future vacation deductions and push a
        // year over its quota. The change itself is not blocked (admin action) —
        // the affected years are surfaced as a non-blocking warning instead.
        warnOnQuotaOverage(quotaWarnings) {
            if (!Array.isArray(quotaWarnings) || quotaWarnings.length === 0) {
                return
            }
            quotaWarnings.forEach((w) => {
                showWarning(t(
                    'worktime',
                    'Achtung: Durch die Profiländerung überschreitet der Urlaub {year} das Kontingent um {days} Tage. Bitte die geplanten Urlaube dieses Mitarbeiters prüfen.',
                    { year: w.year, days: Number(w.over).toLocaleString(getLocale()) },
                ))
            })
        },
    },
}
</script>

